var tool=function(){};tool.prototype={ping:function(e){var n=new Image;return n.ping_checked=!1,n.onload=function(){n.ping_checked||console.log(e+" is alive in",(new Date).getTime()-n.start,"ms"),n.ping_checked=!0},n.onerror=function(t,o,i,c,g){n.ping_checked||console.log(e+" is alive in",(new Date).getTime()-n.start,"ms"),n.ping_checked=!0},n.start=(new Date).getTime(),n.src="//"+e,n.ping_checked||(this.timer=setTimeout(function(){n.ping_checked||console.log(e+" unreachable in",(new Date).getTime()-n.start,"ms"),n.ping_checked=!0},1500)),""}},window.tool=new tool;
